-- Synthetic fixtures only. Always roll back; suitable for a linked development DB.
begin;
create function pg_temp.expect(value boolean, label text) returns void language plpgsql as $$
begin if value is distinct from true then raise exception 'H02 acceptance failed: %',label; end if; end $$;
do $$
declare org uuid := gen_random_uuid(); other_org uuid := gen_random_uuid();
  actor uuid := gen_random_uuid(); second_admin uuid := gen_random_uuid(); client_user uuid := gen_random_uuid();
  client_member uuid; internal_role uuid; client_role uuid; company uuid; grant_id uuid; permission uuid;
  req uuid := gen_random_uuid(); result jsonb; first_result jsonb; original_input jsonb;
begin
  insert into auth.users(id,email) values(actor,'sql-admin-'||actor||'@example.test'),(second_admin,'sql-second-'||second_admin||'@example.test'),(client_user,'sql-client-'||client_user||'@example.test');
  insert into public.profiles(user_id,email,full_name,provisioning_status) select id,email,'SQL fixture','ready' from auth.users where id in(actor,second_admin,client_user);
  insert into public.organizations(id,name) values(org,'SQL acceptance'),(other_org,'Other scope');
  insert into public.organization_members(organization_id,user_id,member_type,is_admin) values(org,actor,'internal',true),(org,second_admin,'internal',true);
  insert into public.organization_members(organization_id,user_id,member_type) values(org,client_user,'client') returning id into client_member;
  insert into public.roles(organization_id,code,name,audience) values(org,'internal','Internal','internal') returning id into internal_role;
  insert into public.roles(organization_id,code,name,audience) values(org,'client','Client','client') returning id into client_role;
  insert into public.permissions(organization_id,module,action,description) values(org,'tributario','view','View'),(org,'tributario','upload','Upload'),(org,'tributario','approve','Approve');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated','session_id',gen_random_uuid())::text,true);
  result := public.h02_context();
  perform pg_temp.expect((result->>'ok')::boolean,'session admission');
  original_input := '{"ruc":"20999999991","legal_name":"SQL company","status":"active","control_start_date":"2026-10-01"}';
  result := public.h02_command(org,req,'CreateOrUpdateCompany',original_input);
  perform pg_temp.expect((result->>'ok')::boolean,'create company: '||result::text);
  first_result := result;
  company := (result->'data'->>'resource_id')::uuid;
  result := public.h02_command(org,req,'CreateOrUpdateCompany',original_input);
  perform pg_temp.expect(result=first_result,'identical retry');
  result := public.h02_command(org,req,'CreateOrUpdateCompany',original_input||'{"legal_name":"Changed input"}');
  perform pg_temp.expect(result->'error'->>'code'='CONFLICT','request reuse rejected');
  result := public.h02_command(org,gen_random_uuid(),'CreateOrUpdateCompany',original_input);
  perform pg_temp.expect(result->'error'->>'code'='CONFLICT','duplicate RUC');
  result := public.h02_command(org,gen_random_uuid(),'CreateOrUpdateCompany',original_input||jsonb_build_object('id',company,'expected_revision',0,'legal_name','First editor'));
  perform pg_temp.expect((result->>'ok')::boolean,'first revision update');
  result := public.h02_command(org,gen_random_uuid(),'CreateOrUpdateCompany',original_input||jsonb_build_object('id',company,'expected_revision',0,'legal_name','Stale editor'));
  perform pg_temp.expect(result->'error'->>'code'='CONFLICT','stale revision rejected');
  result := public.h02_command(org,gen_random_uuid(),'AssignAccess',jsonb_build_object('member_id',client_member,'scope','company','company_id',company,'module','tributario','role_id',client_role,'active',true,'overrides','[]'::jsonb));
  perform pg_temp.expect((result->>'ok')::boolean,'assign client access: '||result::text);
  grant_id := (result->'data'->>'resource_id')::uuid;
  select id into permission from public.permissions where organization_id=org and action='approve';
  result := public.h02_command(org,gen_random_uuid(),'AssignAccess',jsonb_build_object('id',grant_id,'expected_revision',0,'member_id',client_member,'scope','company','company_id',company,'module','tributario','role_id',client_role,'active',true,'overrides',jsonb_build_array(jsonb_build_object('permission_id',permission,'allowed',true))));
  perform pg_temp.expect(result->'error'->>'code'='VALIDATION_ERROR','client review override rejected');
  perform pg_temp.expect((select revision=0 from public.access_grants where id=grant_id),'failed override is atomic');
  select id into permission from public.permissions where organization_id=org and action='upload';
  insert into public.role_permissions(organization_id,role_id,permission_id) values(org,client_role,permission);
  perform pg_temp.expect(private.has_permission(org,client_user,company,'tributario','upload'),'role allows upload');
  result := public.h02_command(org,gen_random_uuid(),'SaveModuleSettings',jsonb_build_object('company_id',company,'module','tributario','delivery_responsible_id',client_user));
  perform pg_temp.expect((result->>'ok')::boolean,'eligible responsible: '||result::text);
  result := public.h02_command(org,gen_random_uuid(),'DeleteEntity',jsonb_build_object('entity','access_grants','id',grant_id,'expected_revision',0,'reason','Separate deletion'));
  perform pg_temp.expect((result->>'ok')::boolean,'delete child');
  result := public.h02_command(org,gen_random_uuid(),'DeleteEntity',jsonb_build_object('entity','companies','id',company,'expected_revision',1,'reason','Pause company'));
  perform pg_temp.expect((result->>'ok')::boolean,'delete parent');
  result := public.h02_command(org,gen_random_uuid(),'CreateOrUpdateCompany',original_input);
  perform pg_temp.expect(result->'error'->>'code'='CONFLICT','deleted RUC remains unique');
  result := public.h02_command(org,gen_random_uuid(),'RestoreEntity',jsonb_build_object('entity','companies','id',company,'expected_revision',2));
  perform pg_temp.expect((result->>'ok')::boolean,'restore parent');
  perform pg_temp.expect((select deleted_at is not null from public.access_grants where id=grant_id),'separately deleted child preserved');
  perform pg_temp.expect((select operation_pauses->0->>'resumed_on' is not null from public.companies where id=company),'pause interval closed');
  perform pg_temp.expect(not private.has_permission(org,client_user,company,'tributario','upload'),'deleted grant does not authorize');
  update public.profiles set enabled=false where user_id=second_admin;
  begin update public.profiles set enabled=false where user_id=actor; raise exception 'Last admin was disabled'; exception when raise_exception then if sqlerrm<>'FORBIDDEN' then raise; end if; end;
  result := public.h02_command(other_org,gen_random_uuid(),'CreateOrUpdateCompany',original_input);
  perform pg_temp.expect(result->'error'->>'code'='FORBIDDEN','cross organization command');
  update public.app_sessions set revoked_at=now(),revocation_reason='Acceptance' where organization_id=org and user_id=actor;
  result := public.h02_context();
  perform pg_temp.expect(result->'error'->>'code'='UNAUTHENTICATED','revoked session not readmitted');
  perform pg_temp.expect(exists(select 1 from public.audit_events where organization_id=org and resource_id=company),'trusted audit written');
  perform pg_temp.expect(not has_table_privilege('authenticated','public.audit_events','INSERT'),'browser cannot forge audit');
  perform pg_temp.expect(not has_function_privilege('authenticated','public.h02_admin_prepare(uuid,uuid,uuid,text,text,uuid)','EXECUTE'),'Auth admin RPC private');
end $$;
rollback;
select 'H02 SQL acceptance passed; fixtures rolled back.' as result;
